internal object UsersUpdateUserOperation {
    /**
     * Update a user's attributes. You can set the user's primary contact identifiers (email address
     * and phone numbers) by updating the `primary_email_address_id` and `primary_phone_number_id`
     * attributes respectively. Both IDs should correspond to verified identifications that belong
     * to the user. You can remove a user's username by setting the username attribute to null or
     * the blank string "". As of API version 2026-05-12, this endpoint no longer accepts
     * `public_metadata`,…
     *
     * @param userId The ID of the user to update
     * @param externalId The ID of the user as used in your external systems or your previous
     *   authentication solution. Must be unique across your instance.
     * @param firstName The first name to assign to the user
     * @param lastName The last name to assign to the user
     * @param locale The locale to assign to the user (e.g., "en-US", "fr-FR")
     * @param timezone The IANA timezone to assign to the user (e.g., "America/New_York",
     *   "Europe/Paris"). Set to null to clear it and allow automatic capture on a later trusted
     *   sign-in.
     * @param primaryEmailAddressId The ID of the email address to set as primary. It must be
     *   verified, and present on the current user.
     * @param notifyPrimaryEmailAddressChanged If set to `true`, the user will be notified that
     *   their primary email address has changed. By default, no notification is sent.
     * @param primaryPhoneNumberId The ID of the phone number to set as primary. It must be
     *   verified, and present on the current user.
     * @param primaryWeb3WalletId The ID of the web3 wallets to set as primary. It must be verified,
     *   and present on the current user.
     * @param username The username to give to the user. It must be unique across your instance.
     * @param profileImageId The ID of the image to set as the user's profile image
     * @param password The plaintext password to give the user. Must be at least 8 characters long,
     *   and cannot be in any list of hacked passwords.
     * @param passwordDigest In case you already have the password digests and not the passwords,
     *   you can use them for the newly created user via this property. The digests should be
     *   generated with one of the supported algorithms. The hashing algorithm can be specified
     *   using the `password_hasher` property.
     * @param passwordHasher The hashing algorithm that was used to generate the password digest.
     *   The algorithms we support at the moment are `bcrypt`, `bcrypt_sha256_django`, `md5`,
     *   `pbkdf2_sha1`, `pbkdf2_sha256`, `pbkdf2_sha256_django`, `pbkdf2_sha512`, `phpass`,
     *   `md5_phpass`, `scrypt_firebase`, `scrypt_werkzeug`, `sha256`, `ldap_ssha`, the `argon2`
     *   variants: `argon2i` and `argon2id`, `sha512_symfony`, the SHA-512 variant of the Symfony
     *   legacy hasher, and `pbkdf2_sha512_hex`, a variant of…
     * @param skipPasswordChecks Set it to `true` if you're updating the user's password and want to
     *   skip any password policy settings check. This parameter can only be used when providing a
     *   `password`.
     * @param signOutOfOtherSessions Set to `true` to sign out the user from all their active
     *   sessions once their password is updated. This parameter can only be used when providing a
     *   `password`.
     * @param totpSecret In case TOTP is configured on the instance, you can provide the secret to
     *   enable it on the specific user without the need to reset it.
     * @param backupCodes If Backup Codes are configured on the instance, you can provide them to
     *   enable it on the specific user without the need to reset them.
     * @param deleteSelfEnabled If true, the user can delete themselves with the Frontend API.
     * @param createOrganizationEnabled If true, the user can create organizations with the Frontend
     *   API.
     * @param legalAcceptedAt A custom timestamp denoting _when_ the user accepted legal
     *   requirements, specified in RFC3339 format.
     * @param skipLegalChecks When set to `true` all legal checks are skipped.
     * @param createOrganizationsLimit The maximum number of organizations the user can create. 0
     *   means unlimited.
     * @param createdAt A custom date/time denoting _when_ the user signed up to the application.
     * @param bypassClientTrust When set to `true`, the user will bypass Device Trust checks during
     *   sign-in.
     */
    fun updateUser(
        clientConfig: ClientConfig,
        request: Users.UpdateUserRequest,
        options: RequestOptions? = null,
    ): User {
        return SdkClient.request<User>(
                SdkClient.RequestSpec(
                    "PATCH",
                    "/users/${SdkClient.encodePathSegment(request.userId)}",
                    config = clientConfig,
                    body = buildUpdateUserBody(request),
                    operationId = "updateUser",
                    decoder = SdkClient.ResponseDecoder.JSON,
                    options = options,
                    errors =
                        mapOf(
                            "400" to ClerkErrors::class.java,
                            "401" to ClerkErrors::class.java,
                            "404" to ClerkErrors::class.java,
                            "409" to ClerkErrors::class.java,
                            "422" to ClerkErrors::class.java,
                        ),
                )
            )
            .data
    }

    private fun buildUpdateUserBody(request: Users.UpdateUserRequest): Map<String, Any?> =
        buildMap {
            putAll(buildUpdateUserBodyPart1(request))
            putAll(buildUpdateUserBodyPart2(request))
            putAll(buildUpdateUserBodyPart3(request))
        }

    private fun buildUpdateUserBodyPart1(request: Users.UpdateUserRequest): Map<String, Any?> =
        SdkClient.bodyMap(
            "external_id" to (request.externalId ?: SdkClient.SdkOptional.Omitted),
            "first_name" to (request.firstName ?: SdkClient.SdkOptional.Omitted),
            "last_name" to (request.lastName ?: SdkClient.SdkOptional.Omitted),
            "locale" to (request.locale ?: SdkClient.SdkOptional.Omitted),
            "timezone" to (request.timezone ?: SdkClient.SdkOptional.Omitted),
            "primary_email_address_id" to
                (request.primaryEmailAddressId ?: SdkClient.SdkOptional.Omitted),
            "notify_primary_email_address_changed" to
                (request.notifyPrimaryEmailAddressChanged ?: SdkClient.SdkOptional.Omitted),
            "primary_phone_number_id" to
                (request.primaryPhoneNumberId ?: SdkClient.SdkOptional.Omitted),
            "primary_web3_wallet_id" to
                (request.primaryWeb3WalletId ?: SdkClient.SdkOptional.Omitted),
            "username" to (request.username ?: SdkClient.SdkOptional.Omitted),
            "profile_image_id" to (request.profileImageId ?: SdkClient.SdkOptional.Omitted),
            "password" to (request.password ?: SdkClient.SdkOptional.Omitted),
        )

    private fun buildUpdateUserBodyPart2(request: Users.UpdateUserRequest): Map<String, Any?> =
        SdkClient.bodyMap(
            "password_digest" to (SdkClient.omitIfNull(request.passwordDigest)),
            "password_hasher" to (SdkClient.omitIfNull(request.passwordHasher)),
            "skip_password_checks" to (request.skipPasswordChecks ?: SdkClient.SdkOptional.Omitted),
            "sign_out_of_other_sessions" to
                (request.signOutOfOtherSessions ?: SdkClient.SdkOptional.Omitted),
            "totp_secret" to (request.totpSecret ?: SdkClient.SdkOptional.Omitted),
            "backup_codes" to (SdkClient.omitIfNull(request.backupCodes)),
            "delete_self_enabled" to (request.deleteSelfEnabled ?: SdkClient.SdkOptional.Omitted),
            "create_organization_enabled" to
                (request.createOrganizationEnabled ?: SdkClient.SdkOptional.Omitted),
            "legal_accepted_at" to (request.legalAcceptedAt ?: SdkClient.SdkOptional.Omitted),
            "skip_legal_checks" to (request.skipLegalChecks ?: SdkClient.SdkOptional.Omitted),
            "create_organizations_limit" to
                (request.createOrganizationsLimit ?: SdkClient.SdkOptional.Omitted),
            "created_at" to (request.createdAt ?: SdkClient.SdkOptional.Omitted),
        )

    private fun buildUpdateUserBodyPart3(request: Users.UpdateUserRequest): Map<String, Any?> =
        SdkClient.bodyMap(
            "bypass_client_trust" to (request.bypassClientTrust ?: SdkClient.SdkOptional.Omitted)
        )
}

